    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Primer cociente q1",
        "pregunta": "Calcule el primer cociente $q_1$ de la división de $s^3 + 4s$ por $2s^2 + 2$.",
        "simbolo": "q_1",
        "unidad": "",
        "valorEsperado": 0.5,
        "solucion": 0.5,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Divida el término de mayor grado del numerador por el del divisor: $s^3 / (2s^2) = 0.5 s$.",
          "Pista 2: El primer cociente es $q_1 = 0.5$.",
          "Pista 3: Resto: $(s^3 + 4s) - 0.5s(2s^2 + 2) = (s^3 + 4s) - (s^3 + s) = 3s$."
        ],
        "explicacionPaso": "$(s^3 + 4s) / (2s^2 + 2) = 0.5s$ con resto $R_1(s) = 3s$. El primer cociente es $q_1 = 0.5$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Segundo cociente q2",
        "pregunta": "Calcule el segundo cociente $q_2$ dividiendo el divisor previo $2s^2 + 2$ por el resto $3s$.",
        "simbolo": "q_2",
        "unidad": "",
        "valorEsperado": 0.667,
        "solucion": 0.667,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Divida $2s^2$ por $3s$: $(2s^2)/(3s) = \\frac{2}{3} s$.",
          "Pista 2: $q_2 = 2/3 \\approx 0.667$.",
          "Pista 3: Resto: $(2s^2 + 2) - \\frac{2}{3}s(3s) = 2$."
        ],
        "explicacionPaso": "$(2s^2 + 2) / (3s) = \\frac{2}{3}s$ con resto $R_2 = 2$. Por lo tanto, $q_2 = 2/3 \\approx 0.667$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tercer cociente q3",
        "pregunta": "Calcule el tercer cociente $q_3$ dividiendo el resto anterior $3s$ por $2$.",
        "simbolo": "q_3",
        "unidad": "",
        "valorEsperado": 1.5,
        "solucion": 1.5,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Divida $3s$ por $2$: $(3s)/2 = 1.5 s$.",
          "Pista 2: El resto es exactamente cero ($R_3 = 0$).",
          "Pista 3: Como $q_1 = 0.5 > 0$, $q_2 = 0.667 > 0$ y $q_3 = 1.5 > 0$, todos los cocientes son positivos y el polinomio es estrictamente Hurwitz."
        ],
        "explicacionPaso": "$(3s)/2 = 1.5s$ con resto 0. Por lo tanto $q_3 = 1.5$. Al ser $q_1, q_2, q_3 > 0$, $P(s)$ es un polinomio de Hurwitz."
      }
    ]
