    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Primer inductor serie L1",
        "pregunta": "Calcule el valor de la inductancia serie $L_1$ (en Henrios).",
        "simbolo": "L_1",
        "unidad": "H",
        "valorEsperado": 2.0,
        "solucion": 2.0,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Divida $(2s^3 + 8s)$ por $(s^2 + 2)$.",
          "Pista 2: Cociente: $2s$. Resto: $8s - 4s = 4s$.",
          "Pista 3: $Z_1(s) = 2s \\implies L_1 = 2.0\\text{ H}$."
        ],
        "explicacionPaso": "Primera división continuada:\\n$\\frac{2s^3 + 8s}{s^2 + 2} = 2s + \\frac{4s}{s^2 + 2}$\\nEl primer cociente es $Z_1(s) = 2s \\implies L_1 = 2.0\\text{ H}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Capacitor en derivación C2",
        "pregunta": "Calcule la capacitancia en derivación $C_2$ (en Faradios).",
        "simbolo": "C_2",
        "unidad": "F",
        "valorEsperado": 0.25,
        "solucion": 0.25,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Invierta el resto para obtener la admitancia: $Y_2(s) = \\frac{s^2 + 2}{4s}$.",
          "Pista 2: Divida $s^2 + 2$ por $4s$: cociente $\\frac{1}{4}s = 0.25s$, resto $2$.",
          "Pista 3: $Y_2(s) = 0.25s + \\frac{2}{4s} \\implies C_2 = 0.25\\text{ F}$."
        ],
        "explicacionPaso": "Invirtiendo el resto:\\n$Y_2(s) = \\frac{s^2 + 2}{4s} = 0.25 s + \\frac{1}{2s}$\\nEl cociente de admitancia es $0.25s \\implies C_2 = 0.25\\text{ F}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Segundo inductor serie L3",
        "pregunta": "Determine el valor del último inductor serie $L_3$ (en Henrios).",
        "simbolo": "L_3",
        "unidad": "H",
        "valorEsperado": 2.0,
        "solucion": 2.0,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Invierta el resto final: $Z_3(s) = \\frac{4s}{2} = 2s$.",
          "Pista 2: $L_3 = 2.0\\text{ H}$."
        ],
        "explicacionPaso": "Invirtiendo el último término residual:\\n$Z_3(s) = \\frac{2s}{1} = 2s \\implies L_3 = 2.0\\text{ H}$. Red en escalera perfectamente sintetizada."
      }
    ]
