    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Impedancia a circuito abierto Zoc",
        "pregunta": "Calcule $Z_{oc}$ vista desde el puerto 1 con el puerto 2 abierto (en Ohms).",
        "simbolo": "Z_{oc}",
        "unidad": "Ω",
        "valorEsperado": 120.0,
        "solucion": 120.0,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Con el puerto 2 abierto, no circula corriente por el segundo resistor de brazo.",
          "Pista 2: $Z_{oc} = Z_1/2 + Z_2$.",
          "Pista 3: $20 + 100 = 120\\,\\Omega$."
        ],
        "explicacionPaso": "Con el puerto de salida abierto: $Z_{oc} = \\frac{Z_1}{2} + Z_2 = 20\\,\\Omega + 100\\,\\Omega = 120.0\\,\\Omega$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Impedancia en cortocircuito Zsc",
        "pregunta": "Calcule $Z_{sc}$ vista desde el puerto 1 con el puerto 2 en cortocircuito (en Ohms).",
        "simbolo": "Z_{sc}",
        "unidad": "Ω",
        "valorEsperado": 36.67,
        "solucion": 36.67,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Cortocircuitar el puerto 2 pone el resistor de brazo derecho en paralelo con la rama shunt.",
          "Pista 2: $Z_{sc} = Z_1/2 + (Z_2 \\parallel Z_1/2)$.",
          "Pista 3: $Z_2 \\parallel (Z_1/2) = (100 \\times 20) / 120 = 2000 / 120 = 16.67\\,\\Omega$. Sume $20 + 16.67 = 36.67\\,\\Omega$."
        ],
        "explicacionPaso": "$Z_{sc} = \\frac{Z_1}{2} + \\left( Z_2 \\parallel \\frac{Z_1}{2} \\right) = 20 + \\frac{100 \\times 20}{120} = 20 + 16.67 = 36.67\\,\\Omega$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Impedancia imagen ZI",
        "pregunta": "Calcule la impedancia imagen $Z_I = \\sqrt{Z_{oc} Z_{sc}}$ (en Ohms).",
        "simbolo": "Z_I",
        "unidad": "Ω",
        "valorEsperado": 66.33,
        "solucion": 66.33,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Aplique la media geométrica: $Z_I = \\sqrt{Z_{oc} \\cdot Z_{sc}}$.",
          "Pista 2: $120 \\times 36.67 = 4400$.",
          "Pista 3: $\\sqrt{4400} \\approx 66.33\\,\\Omega$."
        ],
        "explicacionPaso": "$Z_I = \\sqrt{Z_{oc} \\cdot Z_{sc}} = \\sqrt{120 \\times 36.67} = \\sqrt{4400.4} \\approx 66.33\\,\\Omega$."
      }
    ]
