    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Coeficiente de reflexión de entrada S11",
        "pregunta": "Determine el valor del módulo de reflexión a la entrada $|S_{11}|$ bajo adaptación.",
        "simbolo": "|S_{11}|",
        "unidad": "",
        "valorEsperado": 0.0,
        "solucion": 0.0,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: Por definición de parámetros S, $S_{11}$ es la reflexión en el puerto 1 cuando el puerto 2 está terminado en $Z_0$.",
          "Pista 2: Como el atenuador está diseñado para presentar impedancia de entrada $Z_{in} = 50\\,\\Omega$ cuando la salida se carga con $50\\,\\Omega$, no hay onda reflejada.",
          "Pista 3: $|S_{11}| = 0.0$."
        ],
        "explicacionPaso": "Al estar el atenuador adaptado de forma bilateral a $Z_0 = 50\\,\\Omega$, la impedancia de entrada es exactamente $Z_0$, de modo que la reflexión es nula: $|S_{11}| = 0.0$ (o $S_{11\\text{,dB}} = -\\infty\\text{ dB}$)."
      },
      {
        "id": "paso-2",
        "titulo": "2. Coeficiente de transmisión directa S21",
        "pregunta": "Calcule la magnitud del parámetro de transmisión $|S_{21}|$ para una atenuación de 6 dB.",
        "simbolo": "|S_{21}|",
        "unidad": "",
        "valorEsperado": 0.501,
        "solucion": 0.501,
        "tolerancia": 0.05,
        "pistas": [
          "Pista 1: La atenuación en decibeles es $\\text{Atenuación} = -20 \\log_{10}|S_{21}| = 6\\text{ dB}$.",
          "Pista 2: $|S_{21}| = 10^{-6/20} = 10^{-0.30}$.",
          "Pista 3: $10^{-0.30} \\approx 0.5012$ (aproximadamente la mitad de la tensión incidente)."
        ],
        "explicacionPaso": "Dado que la atenuación nominal es de $6\\text{ dB}$:\\n$|S_{21}| = 10^{-\\frac{\\text{Atenuación}}{20}} = 10^{-6/20} = 10^{-0.3} \\approx 0.501$ (la onda de tensión transmitida al puerto de salida tiene el $50.1\\%$ de la amplitud incidente)."
      }
    ]
